import {KEY,copy,uid,roles,types,fields,options,people,label,catalogs,seed,snapshot,connect,effective,updateVersion,summary,checkConditions,dateFor,validateElement,validateStage} from './model.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db;try{db=JSON.parse(localStorage.getItem(KEY))||seed();}catch{db=seed();}if(db.schema!==1)db=seed();
let page='library',tab='route',editor=null,editorOrigin='',editTab='content',errors={},search='',status='visible',tag='',actor='',routeSearch='',collapsed=new Set(),modals=[],menu=null;
const app=$('#app');
const icon=(n,cls='')=>`<img class="icon ${cls}" src="assets/${n}.svg" alt="">`;
const ib=(a,title,n,attrs='')=>`<button class="icon-btn" data-act="${a}" title="${esc(title)}" aria-label="${esc(title)}" ${attrs}>${icon(n)}</button>`;
const btn=(t,a,c='',attrs='')=>`<button class="btn ${c}" data-act="${a}" ${attrs}>${t}</button>`;
const field=(name,title,value='',type='text',hint='',extra='')=>`<div class="field"><label for="${name}">${title}</label><input class="input ${errors[name]?'invalid':''}" id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}>${hint?`<span class="hint">${hint}</span>`:''}<span class="field-error" data-error="${name}">${esc(errors[name]||'')}</span></div>`;
const select=(name,items,value,attrs='')=>`<select aria-label="${name}" ${attrs}>${items.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select>`;
const searchBox=(id,value,placeholder)=>`<div class="search">${icon('magnifier-outlined')}<input id="${id}" value="${esc(value)}" placeholder="${placeholder}" aria-label="${placeholder}"></div>`;
const check=(name,title,value,attrs='')=>`<label class="check"><input type="checkbox" name="${name}" ${value?'checked':''} ${attrs}>${title}</label>`;
const period=d=>d==null?'Без срока':`${d}-й день от начала плана`;
const statusName=s=>({published:'Опубликован',draft:'Черновик',archived:'Архивный'}[s]);
const badge=s=>`<span class="status ${s}">${statusName(s)}</span>`;
const lib=id=>db.library.find(s=>s.id===id),route=id=>db.route.find(r=>r.id===id);
function save(){try{if(demoKey)sessionStorage.setItem(demoKey,JSON.stringify(db));else localStorage.setItem(KEY,JSON.stringify(db));return true;}catch{toast('Не удалось сохранить: недостаточно места в браузере',true);return false;}}
function toast(t,error=false){const n=$('#toast');n.innerHTML=`<span class="snackbar-icon ${error?'error':''}"></span><span>${esc(t)}</span><button aria-label="Закрыть уведомление" data-act="toast-close">×</button>`;n.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>n.hidden=true,5500);}
function rich(value){return `<div class="rich"><div class="rich-tools"><button data-format="bold" title="Полужирный"><b>Ж</b></button><button data-format="italic" title="Курсив"><i>К</i></button><button data-format="insertUnorderedList" title="Маркированный список">• Список</button></div><div id="description" contenteditable="true" role="textbox" aria-label="Описание этапа" data-placeholder="Опишите цель этапа">${sanitize(value)}</div></div>`;}
function sanitize(v){const t=document.createElement('template');t.innerHTML=v||'';for(const n of [...t.content.querySelectorAll('*')]){if(!['B','STRONG','I','EM','UL','OL','LI','P','BR','DIV'].includes(n.tagName)){n.replaceWith(document.createTextNode(n.textContent));continue;}for(const a of [...n.attributes])n.removeAttribute(a.name);}return t.innerHTML;}
function plain(v){const t=document.createElement('div');t.innerHTML=v||'';return t.textContent;}
function openModal(m){m.returnFocus=document.activeElement;modals.push(m);renderModal();}
function closeModal(){const m=modals.pop();renderModal();if(m?.returnFocus?.isConnected)m.returnFocus.focus();}
function closeAll(){modals=[];renderModal();}
function dirty(){return page==='edit'&&editor&&JSON.stringify(editor)!==editorOrigin;}
function stash(){if(editor){db.editorDrafts[editor.id]=copy(editor);save();}}
function navigate(next,extra={}){if(page==='edit'&&dirty()){openModal({kind:'leave',next,extra});return;}performNav(next,extra);}
function performNav(next,extra={}){page=next;errors={};if(next==='edit'){const s=lib(extra.id);editor=copy(db.editorDrafts[extra.id]||s?.draft||s||{id:extra.id||uid(),name:'',description:'',tags:[],day:1,required:true,order:'free',elements:[],status:'draft',version:0,history:[],draft:null});editorOrigin=JSON.stringify(s?.draft||s||(db.editorDrafts[extra.id]?{}:editor));editTab=extra.uses?'uses':'content';}if(next==='template')tab=extra.tab||'route';history.pushState(null,'',next==='edit'?`#stage/${editor.id}`:next==='template'?`#template/${tab}`:'#library');render();window.scrollTo(0,0);}
function render(){
 $('#sidebar').innerHTML=`<img class="logo" src="assets/skillaz-logo.svg" alt="Skillaz"><div class="search-shell">${icon('magnifier-outlined')}<span>Поиск по меню</span></div><div class="nav-title">Рабочее пространство</div><div class="nav-link">${icon('route-rocket')} Адаптация</div><button class="nav-link nav-sub ${page==='template'?'active':''}" data-act="nav-template">Шаблоны адаптации</button><button class="nav-link nav-sub ${page!=='template'?'active':''}" data-act="nav-library">Справочник этапов</button><div class="sidebar-footer"><a href="#library">Справочник этапов</a><a href="guide.html" target="_blank">Сценарии и ограничения ↗</a><button class="link" data-act="demo">Состояния прототипа</button><span>Локальный прототип · Desktop</span></div>`;
 if(page==='library')renderLibrary();else if(page==='edit')renderEditor();else renderTemplate();
}
function usage(s){const cur=db.route.filter(r=>r.sourceId===s.id);return [...cur.map(r=>({name:db.template.name,version:r.version,current:true})),...(['company','office'].includes(s.id)?[{name:'Адаптация розничной команды',version:1,current:false}]:[])];}
function renderLibrary(){const list=db.library.filter(s=>(status==='visible'?s.status!=='archived':status==='all'||s.status===status)&&(!tag||s.tags.includes(tag))&&s.name.toLowerCase().includes(search.toLowerCase()));app.innerHTML=`<div class="page-head"><h1>Справочник этапов</h1>${btn('+ Создать этап','new','primary')}</div><div class="toolbar">${searchBox('library-search',search,'Поиск по названию этапа')}<div style="width:200px">${select('Статус',[['visible','Без архивных'],['all','Все статусы'],['published','Опубликован'],['draft','Черновик'],['archived','Архивный']],status,'id="status-filter"')}</div><div style="width:190px">${select('Теги',[['','Все теги'],...[...new Set(db.library.flatMap(s=>s.tags))].map(t=>[t,t])],tag,'id="tag-filter"')}</div>${search||tag||status!=='visible'?btn('Сбросить','clear-filters','tertiary'):''}</div>${!db.library.length?`<div class="empty"><h2>Пока нет этапов</h2><p class="muted">Создайте первый этап, чтобы использовать его в шаблонах.</p>${btn('Создать этап','new','primary')}</div>`:!list.length?`<div class="empty"><h2>Этапы не найдены</h2><p class="muted">Измените запрос или очистите фильтры.</p>${btn('Очистить фильтры','clear-filters')}</div>`:`<div class="table-wrap"><table><thead><tr><th>Название этапа</th><th>Теги</th><th>Элементы</th><th>Срок</th><th>Статус</th><th>Шаблоны</th><th>Изменён</th><th></th></tr></thead><tbody>${list.map(s=>`<tr><td><button class="text-link" data-act="edit-stage" data-id="${s.id}">${esc(s.name)}</button><p class="small muted">${esc(plain(s.description))}</p></td><td><div class="table-tags">${s.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div></td><td>${s.elements.length}</td><td class="nowrap">${s.day==null?'Без срока':`День ${s.day}`}</td><td>${badge(s.status)}</td><td><button class="link" data-act="usage" data-id="${s.id}">${usage(s).length}</button></td><td class="small nowrap">${s.updated?.split('-').reverse().join('.')||'—'}</td><td>${ib('stage-menu','Действия этапа','more',`data-id="${s.id}"`)}</td></tr>`).join('')}</tbody></table></div><div class="pagination"><span>Этапов: ${list.length}</span><span>1–${list.length} из ${list.length}</span>${ib('noop','Предыдущая страница','chevron-down-outlined','disabled style="transform:rotate(90deg)"')}${ib('noop','Следующая страница','chevron-down-outlined','disabled style="transform:rotate(-90deg)"')}</div>`}`;}
function renderEditor(){const s=editor,base=lib(s.id);app.innerHTML=`<div class="row between"><button class="back" data-act="nav-library">${icon('arrow-left')} Назад</button><span class="hint" id="save-label">${dirty()?'Есть несохранённые изменения':'Сохранено локально'}</span></div><div class="page-title row"><h1>${esc(s.name||'Новый этап')}</h1>${badge(base?.status||'draft')}<span class="muted">${base?.version?`Версия ${base.version}${base.status==='published'?' · Редактирование новой версии':''}`:'Первая версия'}</span></div><div class="tabs"><button class="${editTab==='content'?'active':''}" data-act="edit-content">Содержание</button><button class="${editTab==='uses'?'active':''}" data-act="edit-uses">Используется в шаблонах <span class="muted">${usage(s).length}</span></button></div>${editTab==='uses'?usesHTML(s):`<div class="form-section stack">${field('stage-name','Название этапа <span class="required">*</span>',s.name)}<div class="field"><label>Описание этапа</label>${rich(s.description)}</div>${field('stage-tags','Теги',s.tags.join(', '),'text','Разделяйте теги запятой. Теги помогают искать этап и не управляют назначением.')}<div class="settings-row"><div class="field"><label for="stage-day">Срок завершения</label><div class="row"><input class="input ${errors.day?'invalid':''}" id="stage-day" type="number" min="1" step="1" value="${s.day??''}" ${s.day==null?'disabled':''} aria-label="Номер дня завершения этапа">${check('stage-no-day','Без срока',s.day==null)}</div><span class="hint">Номер дня от начала индивидуального плана, начиная с 1</span><span class="field-error">${errors.day||''}</span></div>${check('stage-required','Обязательный этап',s.required)}</div><div class="field"><label>Порядок прохождения элементов</label>${orderControl(s.order,'editor')}</div></div><h3 class="mb">Элементы <span class="muted">${s.elements.length}</span></h3>${errors.elements?`<p class="field-error">${errors.elements}</p>`:''}<div class="editor-elements">${s.elements.length?s.elements.map((e,i)=>elementRow(e,null,i,true)).join(''):`<p class="muted" style="padding:20px 0">Добавьте задачу или учебный материал.</p>`}</div><div class="mb">${btn('+ Добавить элемент','add-editor-element','secondary')}</div>`}<div class="bottom-bar"><span class="hint">${base?.status==='published'?'Публикация новой версии не обновит шаблоны автоматически.':'Черновик недоступен для выбора в шаблоне.'}</span>${btn('Сохранить черновик','save-draft')}${btn('Опубликовать','publish','primary')}</div>`;}
function usesHTML(s){return `<div class="tab-content"><h3 class="mb">Использование этапа</h3>${usage(s).length?`<table><thead><tr><th>Шаблон</th><th>Версия этапа</th><th></th></tr></thead><tbody>${usage(s).map(u=>`<tr><td>${esc(u.name)}</td><td>v${u.version}</td><td>${btn('Открыть','open-usage','tertiary',`data-current="${u.current}" data-id="${s.id}"`)}</td></tr>`).join('')}</tbody></table>`:'<p class="muted">Этап пока не используется в шаблонах.</p>'}<p class="hint mt">Публикация новой версии и архивация не меняют подключённые этапы и назначенные планы.</p></div>`;}
function orderControl(v,target,id=''){return `<div class="segmented">${[['free','Свободный'],['sequential','Последовательный']].map(([key,t])=>`<button class="${v===key?'active':''}" data-act="order" data-target="${target}" data-id="${id}" data-value="${key}" aria-pressed="${v===key}">${t}</button>`).join('')}</div>`;}
function elementRow(e,r,i,editable=false){const source=r?.sourceId&&!r.local.some(x=>x.id===e.id);return `<div class="element" data-element="${e.id}">${icon(e.type==='file'?'attachment':e.type==='course'||e.type==='program'?'book':e.type==='link'?'link':'task','type-icon')}<div class="grow"><button class="element-name" data-act="${source?'override-element':'edit-element'}" data-id="${r?.id||''}" data-element="${e.id}">${esc(e.name)}</button><div class="meta"><span>${icon('calendar-outlined')}${period(e.day)}</span><span>${icon('required')}${e.required?'Обязательный':'Необязательный'}</span>${e.duration?`<span>${icon('clock')}${e.duration} минут</span>`:''}<span>${icon(e.role==='leader'?'leader':e.role==='employee'?'user':'group')}${roles[e.role]}</span><span>${types[e.type]}</span></div>${r?.local.some(x=>x.id===e.id)?'<span class="status">Добавлено в шаблоне</span>':''}${r?.overrides[e.id]?`<div class="row small mt"><span class="muted">Изменено в шаблоне</span><button class="link" data-act="reset-override" data-id="${r.id}" data-element="${e.id}">Сбросить</button></div>`:''}</div><div class="actions">${ib(source?'override-element':'edit-element',source?'Изменить срок и обязательность':'Редактировать','edit',`data-id="${r?.id||''}" data-element="${e.id}"`)}${!source?ib('element-menu','Другие действия','more',`data-id="${r?.id||''}" data-element="${e.id}" data-index="${i}" data-editor="${editable}"`):''}</div></div>`;}
const templateTabs=[['info','Основная информация'],['participants','Участники'],['goals','Цели'],['route','Маршрут'],['tasks','Задачи участников'],['faq','FAQ']];
function renderTemplate(){app.innerHTML=`<div class="row between"><button class="back" data-act="nav-library">${icon('arrow-left')} Назад</button><span class="hint">Сохранено локально</span></div><div class="page-title"><h1>${esc(db.template.name)}</h1></div><div class="tabs">${templateTabs.map(([k,t])=>`<button class="${tab===k?'active':''}" data-act="template-tab" data-value="${k}">${t}${k==='route'?` <span class="muted">${db.route.length}</span>`:''}</button>`).join('')}</div>${tab==='route'?routeHTML():otherTab()}<div class="bottom-bar"><span class="hint">Изменения шаблона не меняют назначенные планы</span>${btn('Проверить на сотруднике','preview','secondary')}${btn('Сохранить','save-template','primary')}</div>`;}
function routeHTML(){return `${db.pendingElement?`<div class="summary row between"><span>Есть незавершённая задача для этапа</span>${btn('Продолжить редактирование','resume-element','tertiary')}</div>`:''}<div class="toolbar">${searchBox('route-search',routeSearch,'Поиск по элементам маршрута')}<div class="grow"></div>${btn('Проверить на сотруднике','preview')}</div><div class="filter-line"><span>Фильтр по исполнителю</span>${Object.entries(roles).map(([k,t])=>`<button class="chip ${actor===k?'active':''}" data-act="filter-actor" data-value="${k}">${t} <span class="muted">${db.route.flatMap(r=>effective(r).elements).filter(e=>e.role===k).length}</span></button>`).join('')}${actor||routeSearch?'<button class="link" data-act="clear-route-filter">Сбросить</button>':''}</div>${db.route.length?db.route.map((r,i)=>chapter(r,i)).join(''):'<div class="empty"><h2>В маршруте пока нет этапов</h2><p class="muted">Создайте новый этап или добавьте готовый из справочника.</p></div>'}<div class="mb">${btn('+ Добавить этап','add-stage','secondary')}</div>`;}
function chapter(r,i){const s=effective(r),all=s.elements,filtered=all.filter(e=>(!actor||e.role===actor)&&(!routeSearch||e.name.toLowerCase().includes(routeSearch.toLowerCase())));if((actor||routeSearch)&&!filtered.length)return '';const collapsedNow=collapsed.has(r.id)&&!actor&&!routeSearch;return `<section class="chapter ${collapsedNow?'collapsed':''}" data-stage="${r.id}"><div class="chapter-head"><button class="icon-btn" data-act="collapse" data-id="${r.id}" aria-label="Свернуть или развернуть ${esc(s.name)}" aria-expanded="${!collapsedNow}">${icon('chevron-up','toggle-icon')}</button><div class="grow"><div class="chapter-name">${esc(s.name)}</div><div class="meta"><span>${icon('calendar-outlined')}${period(s.day)}</span><span>${icon('required')}${s.required?'Обязательный':'Необязательный'}</span><span>${all.length} элемента</span></div>${r.sourceId?`<div class="chapter-source"><span class="source-badge">Из справочника · v${r.version}</span><button class="link" data-act="source" data-id="${r.sourceId}">Открыть источник</button>${lib(r.sourceId)?.status==='published'&&lib(r.sourceId).version>r.version?`<button class="link" data-act="update-version" data-id="${r.id}">Доступна новая версия</button>`:''}</div>`:''}<div class="chapter-source"><button class="link" data-act="conditions" data-id="${r.id}">Кому добавлять: ${esc(summary(r.conditions))}</button></div>${r.overrides.stage?`<div class="chapter-source"><span class="muted">Изменено в шаблоне</span><button class="link" data-act="reset-override" data-id="${r.id}" data-element="stage">Сбросить настройки</button></div>`:''}</div>${ib('stage-settings','Настройки этапа','edit',`data-id="${r.id}"`)}${ib('route-menu','Действия этапа','more',`data-id="${r.id}" data-index="${i}"`)}</div><div class="chapter-content">${s.description?`<p>${sanitize(s.description)}</p>`:''}<div class="chapter-controls"><label>Порядок прохождения элементов внутри этапа</label>${orderControl(s.order,'route',r.id)}</div>${filtered.map((e,j)=>elementRow(e,r,j)).join('')}${btn(r.sourceId?'+ Добавить задачу в шаблон':'+ Добавить элемент','add-route-element','tertiary add-element',`data-id="${r.id}"`)}</div><div class="chapter-foot">${icon('arrow-right')}<span>Переход к следующему этапу</span>${select('Переход к следующему этапу',[['none','Без условий'],['complete','После выполнения обязательных элементов'],['time','После наступления срока этапа']],r.transition,`data-transition="${r.id}"`)}</div></section>`;}
function otherTab(){if(tab==='info')return `<div class="tab-content stack">${field('template-name','Название шаблона',db.template.name)}${field('template-description','Описание',db.template.description)}<div class="info-row"><span>Тип плана</span><span>Адаптация</span></div></div>`;if(tab==='participants')return `<div class="tab-content"><h3 class="mb">Участники плана</h3><div class="info-row"><span>Адаптируемый</span><span>Сотрудник, которому назначен план</span></div><div class="info-row"><span>Руководитель плана</span><span>Выбирается в индивидуальном плане</span></div><hr class="divider"><h3 class="mb">Роли помощников в шаблоне</h3>${['hr','buddy'].map(k=>`<div class="info-row"><span>${roles[k]}</span>${check('participant',`Роль доступна для задач шаблона`,db.template.roles.includes(k),`data-role="${k}"`)}</div>`).join('')}<p class="hint mt">Здесь настраиваются роли. Конкретные люди выбираются при назначении плана.</p></div>`;if(tab==='tasks')return `<div class="tab-content"><h3 class="mb">Задачи участников</h3>${db.route.map(r=>{const es=effective(r).elements.filter(e=>e.role!=='employee');return es.length?`<h3 class="mt">${esc(r.base.name)}</h3>${es.map((e,i)=>elementRow(e,r,i)).join('')}`:''}).join('')||'<p class="muted">Задач участников пока нет.</p>'}</div>`;return `<div class="tab-content"><h3>${tab==='goals'?'Цели адаптации':'Частые вопросы'}</h3><p class="muted mt">${tab==='goals'?'В этом шаблоне цели пока не добавлены.':'В этом шаблоне пока нет вопросов.'}</p><p class="hint mt">Раздел сохранён в навигации. В этом прототипе проверяется работа с этапами маршрута.</p>${btn('К маршруту','template-route','tertiary')}</div>`;}
function renderModal(){document.body.style.overflow=modals.length?'hidden':'';$('#layers').innerHTML=modals.map((m,i)=>`<div class="overlay ${m.drawer?'drawer-overlay':''}" style="z-index:${30+i*2}" ${i<modals.length-1?'inert':''}><section role="dialog" aria-modal="true" aria-labelledby="modal-title-${i}" class="modal ${m.wide?'wide':''} ${m.drawer?'drawer':''}"><header class="modal-head"><div class="grow"><h2 id="modal-title-${i}">${modalTitle(m)}</h2>${m.subtitle?`<p>${esc(m.subtitle)}</p>`:''}</div>${ib('close-modal','Закрыть','cross-outlined')}</header><div class="modal-body">${modalBody(m)}</div><footer class="modal-foot">${modalFooter(m)}</footer></section></div>`).join('');const top=$('#layers .overlay:last-child');if(top){requestAnimationFrame(()=>top.querySelector('button,input,select,textarea')?.focus({preventScroll:true}));}}
function modalTitle(m){return {leave:'Сохранить изменения?',archive:'Архивировать этап?',remove:'Удалить этап из маршрута?',removeElement:'Удалить элемент?',picker:'Добавить этапы из справочника',conditions:'Кому добавлять этап',preview:'Проверка на сотруднике',update:'Обновить этап в шаблоне',element:m.edit?'Редактировать элемент':'Добавить элемент',settings:'Настройки этапа',usage:'Использование этапа',demo:'Состояния прототипа',source:'Библиотечная версия этапа',usageOther:'Шаблон · Адаптация розничной команды',localStage:'Новый этап маршрута'}[m.kind]||'';}
function modalBody(m){switch(m.kind){case'leave':return '<p>В этапе есть несохранённые изменения. Сохраните черновик или выйдите без сохранения.</p>';case'archive':return `<p>Этап «${esc(lib(m.id).name)}» станет недоступен для добавления в новые шаблоны.</p><p class="muted mt">Он останется в уже использующих его шаблонах и назначенных планах.</p>`;case'remove':return `<p>Удалить «${esc(route(m.id).base.name)}» из этого шаблона?</p><p class="muted mt">Этап в справочнике и назначенные планы сохранятся. Локальные задачи и условия этого подключения будут удалены.</p>`;case'removeElement':return '<p>Элемент будет удалён только из редактируемого этапа. Продолжить?</p>';case'picker':return pickerBody(m);case'conditions':return conditionBody(m);case'preview':return previewBody(m);case'update':{const r=route(m.id),s=lib(r.sourceId);return `<h3 class="mb">${esc(s.name)}</h3><div class="comparison"><section><h3>В шаблоне · v${r.version}</h3>${r.base.elements.map(e=>`<p>${esc(e.name)}<br><span class="hint">${period(e.day)}</span></p>`).join('')}</section><section><h3>Из справочника · v${s.version}</h3>${s.elements.map(e=>`<p>${!r.base.elements.some(x=>x.id===e.id)?'<span class="status published">Новый</span> ':''}${esc(e.name)}<br><span class="hint">${period(e.day)}</span></p>`).join('')}</section></div><div class="summary">Сохранятся условия включения, ваши сроки и обязательность, порядок прохождения и задачи, добавленные в шаблоне. Назначенные планы не изменятся.</div>`;}case'element':return elementForm(m);case'settings':return `<div class="stack">${m.rid?`<h3>${esc(route(m.rid).base.name)}</h3>`:''}${dayForm(m.value.day)}${check('settings-required','Обязательный этап',m.value.required)}<span class="hint">Обязательность применяется ко всем элементам этапа. Индивидуальные настройки можно изменить после сохранения.</span></div>`;case'usage':return usesHTML(lib(m.id));case'source':{const s=lib(m.id);return `<h3>${esc(s.name)} · v${s.version}</h3><p class="mt">${sanitize(s.description)}</p>${s.elements.map(e=>`<div class="result-item"><strong>${esc(e.name)}</strong><p class="muted small">${types[e.type]} · ${roles[e.role]} · ${period(e.day)}</p></div>`).join('')}<p class="hint mt">Условия и локальные задачи шаблона не входят в библиотечную версию.</p>`;}case'usageOther':return `<h3>Адаптация розничной команды</h3><p class="mt">Используется «${esc(lib(m.id).name)}», версия 1.</p><p class="muted mt">Демонстрация списка использований. Редактируемый шаблон в этом прототипе — «${esc(db.template.name)}».</p>`;case'localStage':return field('local-stage-name','Название этапа <span class="required">*</span>',m.name||'');case'demo':return `<div class="stack"><p class="muted">Демосценарии работают в отдельной копии данных и не стирают ваши изменения.</p>${btn('Пустой справочник','demo-empty')}${btn('Основной пример с условиями','demo-filled')}<a href="index.html#library" target="_blank">Открыть сохранённую рабочую копию ↗</a></div>`;}}
function modalFooter(m){const cancel=btn('Отменить','close-modal');switch(m.kind){case'leave':return `${btn('Остаться','close-modal')}${btn('Выйти без сохранения','discard-leave')}${btn('Сохранить черновик','save-leave','primary')}`;case'archive':return cancel+btn('Архивировать','confirm-archive','primary');case'remove':return cancel+btn('Удалить','confirm-remove','primary');case'removeElement':return cancel+btn('Удалить','confirm-element-remove','primary');case'picker':return `<span class="hint">Выбрано: ${m.selected.length}</span>`+cancel+btn(`Добавить ${m.selected.length} этапов`,'confirm-picker','primary',m.selected.length?'':'disabled');case'conditions':return cancel+btn('Сохранить','save-conditions','primary');case'preview':return '<span class="hint">Проверка не назначает план сотруднику</span>'+btn('Закрыть','close-modal');case'update':return cancel+btn('Обновить в шаблоне','confirm-update','primary');case'element':return cancel+btn(m.edit?'Сохранить':'Добавить элемент','save-element','primary');case'settings':return cancel+btn('Сохранить','save-settings','primary');case'localStage':return cancel+btn('Создать этап','create-local-stage','primary');case'source':return btn('Открыть редактор источника','edit-source','primary');default:return btn('Закрыть','close-modal');}}
function pickerBody(m){const entries=db.library.filter(s=>s.status==='published'&&s.name.toLowerCase().includes(m.search.toLowerCase())&&(!m.tag||s.tags.includes(m.tag)));return `<div class="row mb">${searchBox('picker-search',m.search,'Поиск этапа')}<div style="width:230px">${select('Теги',[['','Все теги'],...[...new Set(db.library.filter(s=>s.status==='published').flatMap(s=>s.tags))].map(t=>[t,t])],m.tag,'id="picker-tag"')}</div></div><p class="hint">Можно выбрать только опубликованные этапы. Порядок добавления — как в справочнике.</p>${entries.map(s=>{const added=db.route.some(r=>r.sourceId===s.id);return `<div class="pick-row"><input type="checkbox" aria-label="Выбрать ${esc(s.name)}" data-pick="${s.id}" ${added?'disabled checked':m.selected.includes(s.id)?'checked':''}><div class="grow"><div class="row between"><h3>${esc(s.name)}</h3>${added?'<span class="status">Уже подключён</span>':''}</div><p class="muted small">${esc(plain(s.description))}</p><div class="meta"><span>${s.elements.length} элемента</span><span>${period(s.day)}</span><span>${[...new Set(s.elements.map(e=>roles[e.role]))].join(', ')}</span></div><button class="link" data-act="picker-expand" data-id="${s.id}" aria-expanded="${m.expanded.includes(s.id)}">${m.expanded.includes(s.id)?'Скрыть состав':'Посмотреть состав'}</button>${m.expanded.includes(s.id)?`<div class="composition">${s.elements.map(e=>`<p>${esc(e.name)}<br><span class="hint">${types[e.type]} · ${roles[e.role]} · ${period(e.day)}</span></p>`).join('')}</div>`:''}</div></div>`;}).join('')||'<div class="empty"><h3>Этапы не найдены</h3><p class="muted">Измените поиск или фильтр тегов.</p></div>'}`;}
function conditionBody(m){const c=m.value;return `<h3 class="mb">${esc(route(m.id).base.name)}</h3><div class="stack"><label class="check"><input type="radio" name="condition-mode" value="all" ${c.mode==='all'?'checked':''}>Всем сотрудникам</label><label class="check"><input type="radio" name="condition-mode" value="conditions" ${c.mode==='conditions'?'checked':''}>По условиям</label></div>${c.mode==='conditions'?`<p class="muted mt">Сотрудник должен подходить под все указанные условия. В каждом условии достаточно одного совпадения.</p>${Object.entries(c.values).map(([f,ids])=>`<div class="condition"><div class="condition-title"><h3>${fields[f]}</h3>${ib('remove-condition','Удалить условие','cross-outlined',`data-field="${f}"`)}</div><div class="selected-values">${ids.map(id=>`<span class="tag">${label(f,id)}</span>`).join('')}</div><div class="multi-options">${searchBox('condition-search-'+f,m.searches[f]||'','Поиск: '+fields[f].toLowerCase())}<div class="options" data-options="${f}">${conditionOptions(m,f)}</div></div>${f==='department'?`<div class="mt">${check('include-children','Включая дочерние подразделения',c.children)}</div>`:''}${m.errors?.[f]?`<p class="field-error">${m.errors[f]}</p>`:''}</div>`).join('')}<div class="mt">${btn('+ Добавить условие','add-condition','tertiary',Object.keys(c.values).length===4?'disabled':'')}</div>${m.errors?.empty?`<p class="field-error">${m.errors.empty}</p>`:''}`:''}<div class="summary"><strong>Кому добавится этап</strong><p class="mt">${esc(summary(c)||'Добавьте условие и выберите значения')}</p></div>`;}
function conditionOptions(m,f){const opts=options[f].filter(([,t])=>t.toLowerCase().includes((m.searches[f]||'').toLowerCase()));return opts.filter(([id])=>!(f==='department'&&id.startsWith('sales-')&&m.treeClosed&&!m.searches[f])).map(([id,t])=>`${f==='department'&&id==='retail'?`<button class="link small" data-act="toggle-tree" aria-expanded="${!m.treeClosed}">${m.treeClosed?'Развернуть подразделения':'Свернуть подразделения'}</button>`:''}<label class="check ${f==='department'&&id.startsWith('sales-')?'child':''}"><input type="checkbox" data-condition="${f}" value="${id}" ${m.value.values[f].includes(id)?'checked':''}>${esc(t)}</label>`).join('')||'<p class="muted">Ничего не найдено</p>';}
function previewBody(m){const p=people.find(p=>p.id===m.person);return `<div class="stack"><div class="field"><label>Сотрудник</label>${select('Сотрудник',people.map(p=>[p.id,`${p.name} · ${label('position',p.position)} · ${p.city?label('city',p.city):'город не указан'}`]),m.person,'id="preview-person"')}</div>${field('preview-date','Дата начала плана',m.start,'date')}<p class="hint">Срок: дата начала + номер дня − 1. Теги этапов не влияют на результат.</p></div>${!m.start?'<p class="field-error">Выберите дату начала плана</p>':db.route.map(r=>{const s=effective(r),result=checkConditions(r.conditions,p);return `<section class="result-item"><span class="status ${result.status}">${{included:'Включён',excluded:'Не включён',unknown:'Не удалось проверить'}[result.status]}</span><h3>${esc(s.name)}</h3>${result.reasons.map(x=>`<p class="${result.status==='unknown'?'required':'muted'}">${esc(x)}</p>`).join('')}${result.status==='included'?`<p class="hint mt">Срок этапа: ${dateFor(m.start,s.day)}</p>${s.elements.map(e=>`<div class="assigned"><strong>${esc(e.name)}</strong><p class="small ${e.role!=='employee'&&!p[e.role]?'required':'muted'}">${e.role==='employee'?esc(p.name):p[e.role]?esc(p[e.role])+' · '+roles[e.role]:`Проблема назначения: ${roles[e.role].toLowerCase()} не найден. Задача сохранена.`}</p><p class="small muted">${dateFor(m.start,e.day)} · ${e.required?'Обязательный':'Необязательный'}</p></div>`).join('')}`:''}</section>`;}).join('')}`;}
function dayForm(v){return `<div class="field"><label for="element-day">Срок завершения</label><div class="row"><input id="element-day" class="input" type="number" min="1" step="1" value="${v??''}" ${v==null?'disabled':''} aria-label="Номер дня завершения элемента">${check('element-no-day','Без срока',v==null)}</div><span class="hint">Номер дня от начала индивидуального плана, начиная с 1</span><span class="field-error" data-error="day"></span></div>`;}
function elementForm(m){const e=m.value,source=m.override;return `<div class="stack">${source?`<h3>${esc(e.name)}</h3><p class="muted">Содержание библиотечной версии доступно только для просмотра. Здесь можно изменить срок и обязательность для этого шаблона.</p>`:`${!m.edit&&!m.localOnly?`<div class="field"><label>Тип элемента</label>${select('Тип элемента',Object.entries(types),e.type,'id="element-type"')}</div>`:''}${['course','program','file'].includes(e.type)?`<div class="field"><label>${e.type==='file'?'Загруженные файлы':'Каталог'}</label>${searchBox('resource-search',m.search||'','Поиск материала')}<div id="resources">${resourceList(m)}</div>${e.type==='file'?'<label class="btn secondary">Загрузить файл<input type="file" id="upload-file" hidden></label><span class="hint">Локально сохраняется название файла; загрузка на сервер не выполняется.</span>':''}<span class="field-error" data-error="resource"></span></div>`:''}${field('element-name','Название <span class="required">*</span>',e.name)}${e.type==='link'?field('element-url','URL <span class="required">*</span>',e.url||'','url','','placeholder="https://"'):''}<div class="field"><label for="element-description">Описание</label><textarea id="element-description">${esc(e.description)}</textarea></div>${e.type==='task'?`<div class="field"><label>Исполнитель</label>${select('Исполнитель',Object.entries(roles).filter(([k])=>['employee','leader'].includes(k)||(m.rid&&db.template.roles.includes(k))),e.role,'id="element-role"')}<span class="hint" id="role-hint">${e.role==='leader'?'Исполнителем станет руководитель, выбранный в индивидуальном плане':m.rid?'Помощники и их роли настраиваются во вкладке «Участники»':'В библиотечном этапе доступны только адаптируемый и руководитель плана'}</span>${m.rid?'<button class="link" data-act="configure-participants">Настроить участников</button>':''}</div>`:'<p class="hint">Исполнитель: адаптируемый</p>'}`}${dayForm(e.day)}${check('element-required','Обязательный элемент',e.required)}${!source?field('element-duration','Длительность, минут',e.duration||'','number','Не влияет на срок завершения','min="1" step="1"'):''}</div>`;}
function resourceList(m){const list=[...(catalogs[m.value.type]||[]),...(m.value.type==='file'?db.uploads:[])].filter(x=>x.name.toLowerCase().includes((m.search||'').toLowerCase()));return list.map(x=>`<label class="check" style="padding:8px 0"><input type="radio" name="resource" value="${x.id}" ${x.id===m.value.resourceId?'checked':''}>${esc(x.name)}${x.duration?` <span class="hint">${x.duration} мин</span>`:''}</label>`).join('')||'<p class="muted">Материалы не найдены</p>';}
function showMenu(anchor,items){$('.drop')?.remove();const r=anchor.getBoundingClientRect(),d=document.createElement('div');d.className='drop';d.setAttribute('role','menu');d.innerHTML=items.map(([t,a,data='',disabled=false])=>`<button role="menuitem" data-act="${a}" ${data} ${disabled?'disabled':''}>${t}</button>`).join('');document.body.append(d);d.style.left=Math.min(window.innerWidth-d.offsetWidth-16,Math.max(16,r.right-d.offsetWidth))+'px';d.style.top=Math.min(r.bottom+6,window.innerHeight-d.offsetHeight-16)+'px';d.querySelector('button:not(:disabled)')?.focus();menu=d;}
function changedEditor(){stash();const n=$('#save-label');if(n)n.textContent='Есть несохранённые изменения';}
function saveEditor(publish=false){errors=validateStage(editor,publish);if(errors.name)errors['stage-name']=errors.name;if(Object.keys(errors).length){editTab='content';renderEditor();toast('Проверьте обязательные поля',true);return false;}let current=lib(editor.id);if(publish){const v=(current?.version||0)+1;const next=snapshot(editor);next.status='published';next.version=v;next.updated=new Date().toISOString().slice(0,10);next.draft=null;next.history=[...(current?.history||[]),snapshot(next)];if(current)Object.assign(current,next);else db.library.push(next);editor=copy(next);}else if(current?.version){current.draft=snapshot(editor);current.updated=new Date().toISOString().slice(0,10);}else{const next=copy(editor);next.status='draft';next.updated=new Date().toISOString().slice(0,10);if(current)Object.assign(current,next);else db.library.push(next);editor=copy(next);}delete db.editorDrafts[editor.id];editorOrigin=JSON.stringify(editor);if(!save())return false;renderEditor();toast(publish?'Этап опубликован. Шаблоны не изменены.':'Черновик сохранён');return true;}
function getElements(rid){if(!rid)return editor.elements;const r=route(rid);return r.sourceId?r.local:r.base.elements;}
function newElement(rid=null){const r=rid&&route(rid);openModal({kind:'element',rid,localOnly:!!r?.sourceId,value:{id:uid(),name:'',type:'task',role:r?.sourceId?'buddy':'employee',day:r?.base.day??editor?.day??1,required:true,description:'',duration:null},search:''});if(r?.sourceId&&!db.template.roles.includes('buddy'))modals.at(-1).value.role='employee';renderModal();}
function readElement(m){const e=m.value;if(!m.override){e.name=$('#element-name').value.trim();e.description=$('#element-description').value;if(e.type==='link')e.url=$('#element-url').value.trim();const d=$('#element-duration').value;e.duration=d?Number(d):null;}e.day=$('[name="element-no-day"]').checked?null:Number($('#element-day').value);e.required=$('[name="element-required"]').checked;return e;}
function showErrors(err){document.querySelectorAll('[data-error]').forEach(n=>n.textContent=err[n.dataset.error]||'');}
function syncModalBody(){const scroll=$('#layers .overlay:last-child .modal-body')?.scrollTop||0;renderModal();const n=$('#layers .overlay:last-child .modal-body');if(n)n.scrollTop=scroll;}
document.addEventListener('click',e=>{
 const fmt=e.target.closest('[data-format]');if(fmt){$('#description').focus();document.execCommand(fmt.dataset.format,false,null);editor.description=sanitize($('#description').innerHTML);changedEditor();return;}
 const b=e.target.closest('[data-act]');if(!b){if(!e.target.closest('.drop')){menu?.remove();menu=null;}return;}if(b.disabled)return;
 const a=b.dataset.act,id=b.dataset.id,m=modals.at(-1);if(menu&&!b.closest('.drop')){menu.remove();menu=null;}else if(b.closest('.drop')){menu.remove();menu=null;}
 switch(a){
 case'toast-close':$('#toast').hidden=true;break;
 case'nav-library':navigate('library');break;case'nav-template':navigate('template');break;
 case'new':navigate('edit',{id:uid()});break;case'edit-stage':navigate('edit',{id});break;
 case'clear-filters':search='';status='visible';tag='';renderLibrary();break;
 case'stage-menu':showMenu(b,[['Открыть','edit-stage',`data-id="${id}"`],['Дублировать','duplicate-stage',`data-id="${id}"`],['Архивировать','archive',`data-id="${id}"`,lib(id).status==='archived']]);break;
 case'duplicate-stage':{const s=copy(lib(id));s.id=uid();s.name+=' — копия';s.status='draft';s.version=0;s.history=[];s.draft=null;s.elements.forEach(x=>x.id=uid());db.library.push(s);save();render();toast('Копия создана как черновик');break;}
 case'archive':openModal({kind:'archive',id});break;case'confirm-archive':lib(m.id).status='archived';save();closeModal();render();toast('Этап архивирован. Подключённые этапы сохранены.');break;
 case'usage':openModal({kind:'usage',id,wide:true});break;
 case'open-usage':{const current=b.dataset.current==='true';closeAll();if(current)navigate('template');else openModal({kind:'usageOther',id});break;}
 case'edit-content':editTab='content';renderEditor();break;case'edit-uses':editTab='uses';renderEditor();break;
 case'save-draft':saveEditor(false);break;case'publish':saveEditor(true);break;
 case'discard-leave':{delete db.editorDrafts[editor.id];save();const {next,extra}=m;editor=null;closeAll();performNav(next,extra);break;}
 case'save-leave':{const {next,extra}=m;if(saveEditor(false)){closeAll();performNav(next,extra);}else closeAll();break;}
 case'close-modal':closeModal();break;
 case'order':{if(b.dataset.target==='editor'){editor.order=b.dataset.value;changedEditor();renderEditor();}else{const r=route(id);if(r.sourceId)r.overrides.stage={...r.overrides.stage,order:b.dataset.value};else r.base.order=b.dataset.value;save();renderTemplate();}break;}
 case'add-editor-element':newElement();break;case'add-route-element':newElement(id);break;
 case'edit-element':case'override-element':{const r=id&&route(id),val=r?effective(r).elements.find(x=>x.id===b.dataset.element):editor.elements.find(x=>x.id===b.dataset.element);openModal({kind:'element',rid:id||null,edit:true,override:a==='override-element',value:copy(val),search:''});break;}
 case'element-menu':{const rid=id||null,idx=getElements(rid).findIndex(x=>x.id===b.dataset.element),attrs=`data-id="${id||''}" data-element="${b.dataset.element}"`;showMenu(b,[['Дублировать','duplicate-element',attrs],['Поднять выше','move-element',attrs+' data-direction="-1"',idx===0],['Опустить ниже','move-element',attrs+' data-direction="1"',idx===getElements(rid).length-1],['Удалить','delete-element',attrs]]);break;}
 case'duplicate-element':{const arr=getElements(id||null),value=copy(arr.find(x=>x.id===b.dataset.element));value.id=uid();value.name+=' — копия';arr.push(value);if(!id)changedEditor();else save();render();toast('Элемент продублирован');break;}
 case'move-element':{const arr=getElements(id||null),from=arr.findIndex(x=>x.id===b.dataset.element),to=from+Number(b.dataset.direction);if(to<0||to>=arr.length)return;arr.splice(to,0,arr.splice(from,1)[0]);if(!id)changedEditor();else save();render();break;}
 case'delete-element':openModal({kind:'removeElement',rid:id||null,eid:b.dataset.element});break;
 case'confirm-element-remove':{const arr=getElements(m.rid);arr.splice(arr.findIndex(x=>x.id===m.eid),1);if(!m.rid)changedEditor();else save();closeModal();render();toast('Элемент удалён');break;}
 case'save-element':{const value=readElement(m),err=validateElement(value);if(value.duration!==null&&(!Number.isInteger(value.duration)||value.duration<1))err['element-duration']='Укажите целое число минут, начиная с 1';if(Object.keys(err).length){showErrors({...err,'element-name':err.name,'element-url':err.url});return;}if(m.override){route(m.rid).overrides[value.id]={day:value.day,required:value.required};}else{const arr=getElements(m.rid),idx=arr.findIndex(e=>e.id===value.id);if(idx>=0)arr[idx]=copy(value);else arr.push(copy(value));}if(m.rid)save();else changedEditor();closeModal();render();toast(m.override?'Настройки изменены только в шаблоне':m.edit?'Элемент сохранён':'Элемент добавлен');break;}
 case'configure-participants':{const saved=copy(readElement(m));db.pendingElement={...m,value:saved,returnFocus:null};save();closeAll();navigate('template',{tab:'participants'});toast('Черновик задачи сохранён. Вернитесь к маршруту, чтобы продолжить.');break;}
 case'template-tab':tab=b.dataset.value;history.replaceState(null,'',`#template/${tab}`);renderTemplate();break;
 case'template-route':tab='route';renderTemplate();break;
 case'save-template':if(save())toast('Шаблон сохранён локально');break;
 case'filter-actor':actor=actor===b.dataset.value?'':b.dataset.value;renderTemplate();break;
 case'clear-route-filter':actor='';routeSearch='';renderTemplate();break;
 case'collapse':if(collapsed.has(id))collapsed.delete(id);else collapsed.add(id);renderTemplate();break;
 case'add-stage':showMenu(b,[['Создать новый','local-stage'],['Из справочника','pick-stages']]);break;
 case'local-stage':openModal({kind:'localStage',name:''});break;
 case'create-local-stage':{const name=$('#local-stage-name').value.trim();if(!name){showErrors({'local-stage-name':'Введите название этапа'});return;}const s={id:uid(),name,description:'',day:1,required:true,order:'free',elements:[],tags:[]};db.route.push({id:uid(),sourceId:null,version:null,base:s,conditions:{mode:'all',values:{},children:true},local:[],overrides:{},transition:'none'});save();closeModal();renderTemplate();break;}
 case'pick-stages':openModal({kind:'picker',wide:true,search:'',tag:'',selected:[],expanded:[]});break;
 case'picker-expand':m.expanded=m.expanded.includes(id)?m.expanded.filter(x=>x!==id):[...m.expanded,id];syncModalBody();break;
 case'confirm-picker':{const chosen=db.library.filter(s=>m.selected.includes(s.id)&&s.status==='published'&&!db.route.some(r=>r.sourceId===s.id));db.route.push(...chosen.map(connect));save();closeModal();renderTemplate();toast(`Добавлено этапов: ${chosen.length}`);break;}
 case'route-menu':{const i=db.route.findIndex(r=>r.id===id),attrs=`data-id="${id}"`;showMenu(b,[['Поднять выше','move-stage',attrs+' data-direction="-1"',i===0],['Опустить ниже','move-stage',attrs+' data-direction="1"',i===db.route.length-1],['Удалить из маршрута','remove-route-stage',attrs]]);break;}
 case'move-stage':{const from=db.route.findIndex(r=>r.id===id),to=from+Number(b.dataset.direction);if(to<0||to>=db.route.length)return;db.route.splice(to,0,db.route.splice(from,1)[0]);save();renderTemplate();break;}
 case'remove-route-stage':openModal({kind:'remove',id});break;case'confirm-remove':db.route=db.route.filter(r=>r.id!==m.id);save();closeModal();renderTemplate();toast('Этап удалён только из этого шаблона');break;
 case'stage-settings':openModal({kind:'settings',rid:id,value:copy(effective(route(id)))});break;
 case'save-settings':{const day=$('[name="element-no-day"]').checked?null:Number($('#element-day').value);if(day!==null&&(!Number.isInteger(day)||day<1)){showErrors({day:'Укажите целый номер дня, начиная с 1'});return;}const r=route(m.rid),required=$('[name="settings-required"]').checked,prev=effective(r);if(r.sourceId){r.overrides.stage={...r.overrides.stage,day,required};if(required!==prev.required){r.base.elements.forEach(e=>r.overrides[e.id]={...r.overrides[e.id],required});r.local.forEach(e=>e.required=required);}}else{Object.assign(r.base,{day,required});if(required!==prev.required)r.base.elements.forEach(e=>e.required=required);}save();closeModal();renderTemplate();toast('Настройки этапа сохранены');break;}
 case'reset-override':delete route(id).overrides[b.dataset.element];save();renderTemplate();toast('Настройки возвращены к библиотечной версии');break;
 case'source':openModal({kind:'source',id,wide:true});break;case'edit-source':{const id=m.id;closeAll();navigate('edit',{id});break;}
 case'conditions':openModal({kind:'conditions',id,drawer:true,value:copy(route(id).conditions),searches:{},errors:{}});break;
 case'toggle-tree':m.treeClosed=!m.treeClosed;syncModalBody();break;
 case'add-condition':showMenu(b,Object.entries(fields).filter(([f])=>!(f in m.value.values)).map(([f,t])=>[t,'insert-condition',`data-field="${f}"`]));break;
 case'insert-condition':m.value.values[b.dataset.field]=[];syncModalBody();break;
 case'remove-condition':delete m.value.values[b.dataset.field];delete m.errors[b.dataset.field];syncModalBody();break;
 case'save-conditions':{m.errors={};if(m.value.mode==='conditions'){if(!Object.keys(m.value.values).length)m.errors.empty='Добавьте хотя бы одно условие';for(const [f,ids] of Object.entries(m.value.values))if(!ids.length)m.errors[f]='Выберите значение или удалите условие';}if(Object.keys(m.errors).length){syncModalBody();return;}route(m.id).conditions=m.value.mode==='all'?{mode:'all',values:{},children:true}:copy(m.value);save();closeModal();renderTemplate();toast('Условия этапа сохранены');break;}
 case'preview':openModal({kind:'preview',drawer:true,person:'p1',start:'2026-11-02'});break;
 case'update-version':openModal({kind:'update',id,wide:true});break;
 case'confirm-update':{const r=route(m.id);updateVersion(r,lib(r.sourceId));save();closeModal();renderTemplate();toast('Версия обновлена. Условия и локальные задачи сохранены.');break;}
 case'demo':openModal({kind:'demo'});break;
 case'demo-empty':window.open('index.html?demo=empty#library','_blank');break;
 case'demo-filled':window.open('index.html?demo=filled#template/route','_blank');break;
 case'resume-element':{const draft=copy(db.pendingElement);delete db.pendingElement;save();openModal(draft);break;}
 }
});
document.addEventListener('input',e=>{const t=e.target,id=t.id,m=modals.at(-1);
 if(id==='library-search'){search=t.value;renderKeepFocus(renderLibrary,id);}else if(id==='route-search'){routeSearch=t.value;renderKeepFocus(renderTemplate,id);}else if(id==='stage-name'){editor.name=t.value;changedEditor();}else if(id==='description'){editor.description=sanitize(t.innerHTML);changedEditor();}else if(id==='stage-tags'){editor.tags=t.value.split(',').map(x=>x.trim()).filter(Boolean);changedEditor();}else if(id==='stage-day'){editor.day=t.value===''?'':Number(t.value);changedEditor();}else if(id==='picker-search'){m.search=t.value;renderKeepFocus(renderModal,id);}else if(id.startsWith('condition-search-')){const f=id.slice(17);m.searches[f]=t.value;document.querySelector(`[data-options="${f}"]`).innerHTML=conditionOptions(m,f);}else if(id==='resource-search'){m.search=t.value;$('#resources').innerHTML=resourceList(m);}else if(id==='template-name'){db.template.name=t.value;save();}else if(id==='template-description'){db.template.description=t.value;save();}
});
document.addEventListener('change',async e=>{const t=e.target,id=t.id,m=modals.at(-1);
 if(id==='status-filter'){status=t.value;renderLibrary();}else if(id==='tag-filter'){tag=t.value;renderLibrary();}else if(t.name==='stage-no-day'){editor.day=t.checked?null:1;changedEditor();renderEditor();}else if(t.name==='stage-required'){editor.required=t.checked;editor.elements.forEach(e=>e.required=t.checked);changedEditor();renderEditor();}else if(t.dataset.pick){m.selected=t.checked?[...m.selected,t.dataset.pick]:m.selected.filter(x=>x!==t.dataset.pick);syncModalBody();}else if(id==='picker-tag'){m.tag=t.value;syncModalBody();}else if(t.name==='condition-mode'){m.value.mode=t.value;m.errors={};syncModalBody();}else if(t.dataset.condition){const f=t.dataset.condition;m.value.values[f]=t.checked?[...m.value.values[f],t.value]:m.value.values[f].filter(x=>x!==t.value);delete m.errors[f];syncModalBody();}else if(t.name==='include-children'){m.value.children=t.checked;syncModalBody();}else if(id==='preview-person'){m.person=t.value;syncModalBody();}else if(id==='preview-date'){m.start=t.value;syncModalBody();}else if(id==='element-type'){readElement(m);m.value={...m.value,type:t.value,name:'',resourceId:null,url:'',role:'employee',duration:null};m.search='';syncModalBody();}else if(t.name==='resource'){readElement(m);const x=[...(catalogs[m.value.type]||[]),...db.uploads].find(x=>x.id===t.value);Object.assign(m.value,{resourceId:x.id,name:x.name,duration:x.duration||null});syncModalBody();}else if(id==='element-role'){m.value.role=t.value;$('#role-hint').textContent=t.value==='leader'?'Исполнителем станет руководитель, выбранный в индивидуальном плане':t.value==='employee'?'Задачу выполнит сотрудник, которому назначен план':'Исполнитель будет выбран для этой роли в индивидуальном плане';}else if(t.name==='element-no-day'){if(m.kind==='element')readElement(m);else m.value.day=t.checked?null:1;m.value.day=t.checked?null:1;syncModalBody();}else if(id==='upload-file'){const f=t.files?.[0];if(!f)return;readElement(m);const x={id:uid(),name:f.name,size:f.size};db.uploads.push(x);save();m.value.resourceId=x.id;m.value.name=x.name;syncModalBody();toast('Файл выбран локально');}else if(t.dataset.transition){const r=route(t.dataset.transition);if(t.value==='time'&&effective(r).day==null){t.value=r.transition;toast('Для перехода по сроку сначала задайте срок этапа',true);return;}r.transition=t.value;save();}else if(t.name==='participant'){const k=t.dataset.role;const used=db.route.some(r=>effective(r).elements.some(e=>e.role===k));if(!t.checked&&used){t.checked=true;toast('Роль используется в задачах. Сначала смените исполнителя этих задач.',true);return;}db.template.roles=t.checked?[...new Set([...db.template.roles,k])]:db.template.roles.filter(r=>r!==k);save();}
});
function renderKeepFocus(fn,id){const n=document.getElementById(id),p=n?.selectionStart;fn();requestAnimationFrame(()=>{const v=document.getElementById(id);v?.focus();if(p!=null)v?.setSelectionRange(p,p);});}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(menu){menu.remove();menu=null;}else if(modals.length)closeModal();}if(e.key==='Tab'&&modals.length){const nodes=[...$('#layers .overlay:last-child').querySelectorAll('button:not(:disabled),input:not(:disabled),select,textarea,a[href]')].filter(n=>n.getClientRects().length);if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.addEventListener('paste',e=>{if(e.target.id==='description'){e.preventDefault();document.execCommand('insertText',false,e.clipboardData.getData('text/plain'));editor.description=sanitize(e.target.innerHTML);changedEditor();}});
window.addEventListener('popstate',()=>{const h=location.hash.slice(1).split('/');navigate(h[0]==='stage'?'edit':h[0]==='template'?'template':'library',{id:h[1],tab:h[1]});});
window.addEventListener('beforeunload',e=>{if(dirty()){e.preventDefault();e.returnValue='';}});
const demo=new URLSearchParams(location.search).get('demo');let demoKey=null;if(demo){demoKey=KEY+'-demo-'+demo;try{db=JSON.parse(sessionStorage.getItem(demoKey))||seed();}catch{db=seed();}if(demo==='empty'&&!sessionStorage.getItem(demoKey))db.library=[];if(demo==='filled'&&!sessionStorage.getItem(demoKey)){const office=connect(lib('office'));office.conditions={mode:'conditions',values:{position:['sales','senior'],city:['msk']},children:true};office.local.push({id:'local-access',name:'Помочь с доступами',type:'task',role:'buddy',day:1,required:true,description:'Проверить доступ к рабочим системам.',duration:15});db.route.splice(1,0,office);}}
function initial(){const hash=location.hash.slice(1).split('/');if(hash[0]==='stage'&&(lib(hash[1])||db.editorDrafts[hash[1]]))performNav('edit',{id:hash[1]});else if(hash[0]==='template')performNav('template',{tab:hash[1]||'route'});else performNav('library');}
initial();
